INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(521498, 52088, 327, '<td valign="top">Nice colors and not a bad idea for the challenge. I do however feel this looks more oof then a blur. Perhaps the  black on the left should of been hidden?. Your light is nice and again the colors are really vivid.</td>', 'Nice colors and not a bad idea for the challenge. I do however feel this looks more oof then a blur. Perhaps the  black on the left should of been hidden?. Your light is nice and again the colors are really vivid.', '2003-12-24 00:09:29.000000', NULL, 1),
