(521501, 52109, 772, '<td valign="top">the exposure here seems a bit weak.</td>', 'the exposure here seems a bit weak.', '2003-12-24 00:10:20.000000', NULL, 1),
(521503, 51934, 772, '<td valign="top">I like the monotonous feeling of this image... nice use of ''lack of color'' :)</td>', 'I like the monotonous feeling of this image... nice use of ''lack of color'' :)', '2003-12-24 00:10:51.000000', NULL, 1),
(521504, 51991, 327, '<td valign="top">Total despair and sadness. Love the light and mood.</td>', 'Total despair and sadness. Love the light and mood.', '2003-12-24 00:10:57.000000', NULL, 1),
(521506, 52072, 772, '<td valign="top">excellent photo... very nicely composed.. i can feel the spirit of this shot.. hear the waves and smell the air...</td>', 'excellent photo... very nicely composed.. i can feel the spirit of this shot.. hear the waves and smell the air...', '2003-12-24 00:11:30.000000', NULL, 1),
(521507, 51885, 327, '<td valign="top">Magical! Very good.</td>', 'Magical! Very good.', '2003-12-24 00:11:42.000000', NULL, 1),
(521509, 51574, 772, '<td valign="top">The tilt of the horizon makes this shot feel a bit unbalanced...</td>', 'The tilt of the horizon makes this shot feel a bit unbalanced...', '2003-12-24 00:12:12.000000', NULL, 1),
(521514, 51517, 14863, '<td valign="top">This is very cool and a good idea- a bit grainy but very interesting</td>', 'This is very cool and a good idea- a bit grainy but very interesting', '2003-12-24 00:14:16.000000', NULL, 1),
(521515, 52117, 772, '<td valign="top">i like the theme and composition of this shot, but the color cast feels a bit awkward.</td>', 'i like the theme and composition of this shot, but the color cast feels a bit awkward.', '2003-12-24 00:14:52.000000', NULL, 1),
