(521890, 51892, 14401, '<td valign="top">Focus could be a bit sharper - and the horizon line doesn''t look straight.  Beach scenes are really hard to capture - particularly on overcast or cloudy days.</td>', 'Focus could be a bit sharper - and the horizon line doesn''t look straight.  Beach scenes are really hard to capture - particularly on overcast or cloudy days.', '2003-12-24 07:12:01.000000', NULL, 1),
(521891, 51653, 7966, '<td valign="top">good idea but that pole and white streek are REALLY destracting. 5</td>', 'good idea but that pole and white streek are REALLY destracting. 5', '2003-12-24 07:12:54.000000', NULL, 1),
(521892, 51877, 7966, '<td valign="top">bad quality/not in focus</td>', 'bad quality/not in focus', '2003-12-24 07:13:59.000000', NULL, 1),
(521893, 51661, 14401, '<td valign="top">Interesting take on the subject.  Good shot.</td>', 'Interesting take on the subject.  Good shot.', '2003-12-24 07:14:26.000000', NULL, 1),
(521894, 52051, 13759, '<td valign="top">Well defined subject, it matters! I saw some "pixelite" in this. Had you used a large digital zoom? It really turns the colors and subjects unsharp.</td>', 'Well defined subject, it matters! I saw some "pixelite" in this. Had you used a large digital zoom? It really turns the colors and subjects unsharp.', '2003-12-24 07:15:04.000000', NULL, 1),
