(521905, 51885, 13759, '<td valign="top">Ok, ok... this is only a beach! Beautiful shot. The moon lit over the water was great.</td>', 'Ok, ok... this is only a beach! Beautiful shot. The moon lit over the water was great.', '2003-12-24 07:19:23.000000', NULL, 1),
(521906, 51569, 14401, '<td valign="top">Pretty shot.  Would like to see a little brighter colors, but that''s hard to achieve with the fog I know.</td>', 'Pretty shot.  Would like to see a little brighter colors, but that''s hard to achieve with the fog I know.', '2003-12-24 07:20:00.000000', NULL, 1),
(521907, 51502, 14401, '<td valign="top">Cool shot.  Good representation of the subject.</td>', 'Cool shot.  Good representation of the subject.', '2003-12-24 07:21:11.000000', NULL, 1),
(521910, 51991, 14401, '<td valign="top">Stark.  Sad in it''s implication - but very nicely done!</td>', 'Stark.  Sad in it''s implication - but very nicely done!', '2003-12-24 07:23:51.000000', NULL, 1),
(521912, 52074, 14401, '<td valign="top">Beautiful!  One of the few instances where reflection and glare did not detract from the image!</td>', 'Beautiful!  One of the few instances where reflection and glare did not detract from the image!', '2003-12-24 07:28:11.000000', NULL, 1),
(521914, 52105, 14401, '<td valign="top">Lovely photo!  I''d like a little less foreground, but that''s easily fixed :-)</td>', 'Lovely photo!  I''d like a little less foreground, but that''s easily fixed :-)', '2003-12-24 07:30:32.000000', NULL, 1),
