INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(522525, 51892, 13749, '<td valign="top">interesting.. i''m curious to see where this was taken - it almost looka as if the ocean abruptly ends at that wall.  i would''ve liked to see a little mor e of the focus on the ship than the foreground.</td>', 'interesting.. i''m curious to see where this was taken - it almost looka as if the ocean abruptly ends at that wall.  i would''ve liked to see a little mor e of the focus on the ship than the foreground.', '2003-12-24 17:21:15.000000', NULL, 1),
(522590, 51297, 13474, '<td valign="top">very cool pic, love the colours and the idea is great. well done and all the best!</td>', 'very cool pic, love the colours and the idea is great. well done and all the best!', '2003-12-24 18:31:52.000000', NULL, 1),
(522598, 51395, 2158, '<td valign="top">The light on the beetle seems a bit too harsh; otherwise a very good job.</td>', 'The light on the beetle seems a bit too harsh; otherwise a very good job.', '2003-12-24 18:38:11.000000', NULL, 1),
(522612, 52071, 8816, '<td valign="top">Awesome shot, I love it.  Lighting is well done, composition excellent, follows the challenge perfectly.  This also looks more deeply into the challenge, and has a very artistic element to it.  You really managed to create a clear line through the girl.  Well done, very well done!  Very creative.  10</td>', 'Awesome shot, I love it.  Lighting is well done, composition excellent, follows the challenge perfectly.  This also looks more deeply into the challenge, and has a very artistic element to it.  You really managed to create a clear line through the girl.  Well done, very well done!  Very creative.  10', '2003-12-24 19:03:31.000000', NULL, 1),
(522614, 51432, 2158, '<td valign="top">Damn, I actually feel sorry for the little guy.  Wouldn''t like to meet him face to face though.  Nice shot!</td>', 'Damn, I actually feel sorry for the little guy.  Wouldn''t like to meet him face to face though.  Nice shot!', '2003-12-24 19:12:00.000000', NULL, 1),
(522620, 51468, 10170, '<td valign="top">Clever idea and very well executed.</td>', 'Clever idea and very well executed.', '2003-12-24 19:26:30.000000', NULL, 1),
(522623, 52035, 10170, '<td valign="top">Love it.  Great exposure, which I would guess would not be easy with this.</td>', 'Love it.  Great exposure, which I would guess would not be easy with this.', '2003-12-24 19:31:17.000000', NULL, 1),
(522624, 52074, 10170, '<td valign="top">Very nicely done indeed.  I love the contrast between the sharp glass and the softer areas.</td>', 'Very nicely done indeed.  I love the contrast between the sharp glass and the softer areas.', '2003-12-24 19:32:42.000000', NULL, 1),
(522628, 51991, 10170, '<td valign="top">Excellent lighting makes this an absolutely stunning photo.  Great stuff!</td>', 'Excellent lighting makes this an absolutely stunning photo.  Great stuff!', '2003-12-24 19:33:54.000000', NULL, 1),
(522630, 52057, 10170, '<td valign="top">Very nicelt done indeed.  Good use of colours, nice and sharp.</td>', 'Very nicelt done indeed.  Good use of colours, nice and sharp.', '2003-12-24 19:36:22.000000', NULL, 1),
(522634, 52011, 10170, '<td valign="top">Beautiful shot, especially the texture of the ice.</td>', 'Beautiful shot, especially the texture of the ice.', '2003-12-24 19:43:08.000000', NULL, 1),
(522635, 52010, 10170, '<td valign="top">Very simple and highly effective.</td>', 'Very simple and highly effective.', '2003-12-24 19:44:35.000000', NULL, 1),
(522636, 51591, 2158, '<td valign="top">I wish there had been a bit more light on the top leaf, but it works pretty well as it is.</td>', 'I wish there had been a bit more light on the top leaf, but it works pretty well as it is.', '2003-12-24 19:44:37.000000', NULL, 1),
(522637, 51429, 10170, '<td valign="top">Nice photo of the revolver, but the border really sucks here, sorry.  It distracts completely away from an otherwise excellent shot.</td>', 'Nice photo of the revolver, but the border really sucks here, sorry.  It distracts completely away from an otherwise excellent shot.', '2003-12-24 19:46:03.000000', NULL, 1),
(522641, 51432, 6624, '<td valign="top">technically very good but as an image it is offensive to me and I personally see no connection to the challenge</td>', 'technically very good but as an image it is offensive to me and I personally see no connection to the challenge', '2003-12-24 19:52:55.000000', NULL, 1),
(522643, 51540, 1570, '<td valign="top">i like this a lot, actually, i had a similar idea, but your interpretation is much better, 10...  at first i didn''t understand why the thumbs aren''t touching, but this fact makes it more dynamic... i hope that your picture is doing better than mine, it''s really low at the moment...</td>', 'i like this a lot, actually, i had a similar idea, but your interpretation is much better, 10...  at first i didn''t understand why the thumbs aren''t touching, but this fact makes it more dynamic... i hope that your picture is doing better than mine, it''s really low at the moment...', '2003-12-24 19:56:28.000000', NULL, 1),
(522655, 51755, 14980, '<td valign="top">lovely colour contrast</td>', 'lovely colour contrast', '2003-12-24 21:07:56.000000', NULL, 1),
(522657, 52092, 14980, '<td valign="top">this photo would make more "sense" if it were spun 180 degrees... great pic anyway</td>', 'this photo would make more "sense" if it were spun 180 degrees... great pic anyway', '2003-12-24 21:09:38.000000', NULL, 1),
(522672, 52117, 6179, '<td valign="top">Like the composition but this photo would have been much more dynamic with an improved depth of field. Also looks a little grainy...maybe a lower ISO with a longer exposure would do the trick.</td>', 'Like the composition but this photo would have been much more dynamic with an improved depth of field. Also looks a little grainy...maybe a lower ISO with a longer exposure would do the trick.', '2003-12-24 21:53:58.000000', NULL, 1),
(522674, 52016, 13403, '<td valign="top">scary..  i like it.. (save for the border)</td>', 'scary..  i like it.. (save for the border)', '2003-12-24 21:55:20.000000', NULL, 1),
(522675, 52057, 6179, '<td valign="top">I am somehow drawn to this photo... maybe it''s the gin.</td>', 'I am somehow drawn to this photo... maybe it''s the gin.', '2003-12-24 21:55:39.000000', NULL, 1),
(522679, 52080, 6179, '<td valign="top">Excellent action photo.</td>', 'Excellent action photo.', '2003-12-24 21:58:24.000000', NULL, 1),
(522681, 52015, 6179, '<td valign="top">I like the composition but I would have sized the photo closer to the max allowable so that everyone can see more detail. I think you will take a hit in your score because of the size.</td>', 'I like the composition but I would have sized the photo closer to the max allowable so that everyone can see more detail. I think you will take a hit in your score because of the size.', '2003-12-24 22:02:16.000000', NULL, 1),
(522682, 51772, 6179, '<td valign="top">Lovely lines...your DOF is perfect.</td>', 'Lovely lines...your DOF is perfect.', '2003-12-24 22:03:51.000000', NULL, 1),
(522683, 51974, 6179, '<td valign="top">Other that doubting if this photo really meets the challenge I believe you should have sized your photo to more closely fit the max dimensions allowed in the contest. Smaller photos tend to show less detail and generally score lower.</td>', 'Other that doubting if this photo really meets the challenge I believe you should have sized your photo to more closely fit the max dimensions allowed in the contest. Smaller photos tend to show less detail and generally score lower.', '2003-12-24 22:10:09.000000', NULL, 1),
(522685, 51854, 11832, '<td valign="top">great shot and idea,</td>', 'great shot and idea,', '2003-12-24 22:15:58.000000', NULL, 1),
(522688, 51558, 6179, '<td valign="top">One of the best photographic rules I''ve learned is that, every time you''re tempted to use the camera''s built-in flash, you have to pinch youself. Pretty soon, you stop being tempted. Nothing screams ''snapshot'' so loudly as the combination of overexposed highlights and background falloff produced by these (damned) things. Natural light is always the best but in the absence of natural light any other light source is better than the built in flash.  I also do not know if this photo really meets the challenge.</td>', 'One of the best photographic rules I''ve learned is that, every time you''re tempted to use the camera''s built-in flash, you have to pinch youself. Pretty soon, you stop being tempted. Nothing screams ''snapshot'' so loudly as the combination of overexposed highlights and background falloff produced by these (damned) things. Natural light is always the best but in the absence of natural light any other light source is better than the built in flash.  I also do not know if this photo really meets the challenge.', '2003-12-24 22:20:52.000000', NULL, 1),
(522689, 51429, 6179, '<td valign="top">Nice image however I could have done without the rainbow border. I find it a bit distracting from the photo. A border should compliment the photo.</td>', 'Nice image however I could have done without the rainbow border. I find it a bit distracting from the photo. A border should compliment the photo.', '2003-12-24 22:23:24.000000', NULL, 1),
(522695, 52084, 6179, '<td valign="top">I noticed that you only used a little over 65 kb of the 150 kb file size allowed by the rules. The increase would really sharpen the shot. Use all of the file size you can.</td>', 'I noticed that you only used a little over 65 kb of the 150 kb file size allowed by the rules. The increase would really sharpen the shot. Use all of the file size you can.', '2003-12-24 22:35:32.000000', NULL, 1),
(522698, 52031, 11531, '<td valign="top">hey dude, this picture is awesome, is strong, and i like the bloody colors</td>', 'hey dude, this picture is awesome, is strong, and i like the bloody colors', '2003-12-24 23:01:20.000000', NULL, 1),
(522699, 51987, 14193, '<td valign="top">I am not sure this meets all the rules, but it is sooooo awesome a shot, I am gonna give it an 8 anyway!</td>', 'I am not sure this meets all the rules, but it is sooooo awesome a shot, I am gonna give it an 8 anyway!', '2003-12-24 23:04:12.000000', NULL, 1),
(522700, 51432, 15360, '<td valign="top">Outstanding photography and imagination.</td>', 'Outstanding photography and imagination.', '2003-12-24 23:05:32.000000', NULL, 1),
(522712, 52116, 10145, '<td valign="top">Good interpretation of the challenge. This man looks like he is on the edge of something...society perhaps. This has a feel to it I can''t describe. Nice work..8</td>', 'Good interpretation of the challenge. This man looks like he is on the edge of something...society perhaps. This has a feel to it I can''t describe. Nice work..8', '2003-12-25 00:06:33.000000', NULL, 1),
(522713, 51987, 10145, '<td valign="top">Powerful!</td>', 'Powerful!', '2003-12-25 00:06:46.000000', NULL, 1),
(522723, 51810, 10222, '<td valign="top">Great Shot.<br/> <br/>I like the bright mountains at the back. 10.</td>', 'Great Shot. I like the bright mountains at the back. 10.', '2003-12-25 00:52:25.000000', NULL, 1),
(522733, 51810, 3273, '<td valign="top">This is a striking photograph but I don''t like the persons pose and waving at the camera.  I think it would be better if they were just standing there looking into the distance.  Good shot though and it certainly meets the challenge in my view.</td>', 'This is a striking photograph but I don''t like the persons pose and waving at the camera.  I think it would be better if they were just standing there looking into the distance.  Good shot though and it certainly meets the challenge in my view.', '2003-12-25 02:06:25.000000', NULL, 1),
(522735, 52099, 13749, '<td valign="top">the photo seems a bit out of focus (especially for such a "sharp" subject) and is either rusty or could use some white balance.. either way, the yellow tint isn''t too attractive to me.  interesting border.. i understand what you''re trying to convey and i think it adds to the image for me.. but also think that some won''t understand and you might lose some points for that.</td>', 'the photo seems a bit out of focus (especially for such a "sharp" subject) and is either rusty or could use some white balance.. either way, the yellow tint isn''t too attractive to me.  interesting border.. i understand what you''re trying to convey and i think it adds to the image for me.. but also think that some won''t understand and you might lose some points for that.', '2003-12-25 03:14:59.000000', NULL, 1),
(522736, 52041, 13749, '<td valign="top">nice.  i like the steel/strong boundaries between the elegant gardens + architecture and the viewer.  seems slightly blown out in the upper left portion.</td>', 'nice.  i like the steel/strong boundaries between the elegant gardens + architecture and the viewer.  seems slightly blown out in the upper left portion.', '2003-12-25 03:17:28.000000', NULL, 1),
(522737, 51517, 13749, '<td valign="top">i like the interpretation and execution.. very good facial expression and composition.  i also think the graininess works well here.  perfect black in the mouth is also a nice touch.</td>', 'i like the interpretation and execution.. very good facial expression and composition.  i also think the graininess works well here.  perfect black in the mouth is also a nice touch.', '2003-12-25 03:19:53.000000', NULL, 1),
(522742, 51321, 14891, '<td valign="top">This would be a great picture if those dormant trees were left out.</td>', 'This would be a great picture if those dormant trees were left out.', '2003-12-25 03:24:40.000000', NULL, 1),
