(523032, 52051, 3665, '<td valign="top">Beautiful scenery shot of a gorgeous view!  Too bad the picture shows the pixels.</td>', 'Beautiful scenery shot of a gorgeous view!  Too bad the picture shows the pixels.', '2003-12-25 22:10:08.000000', NULL, 1),
(523033, 51468, 12253, '<td valign="top">Well seen!  Good lighting as well.  The tree branches appear to have halos as does the grass, suggesting some oversharpening, though.  You might want to watch for that in the future.</td>', 'Well seen!  Good lighting as well.  The tree branches appear to have halos as does the grass, suggesting some oversharpening, though.  You might want to watch for that in the future.', '2003-12-25 22:10:59.000000', NULL, 1),
