(523177, 51987, 3306, '<td valign="top">Interesting concept. Very creative.</td>', 'Interesting concept. Very creative.', '2003-12-26 08:12:02.000000', NULL, 1),
(523178, 51854, 4517, '<td valign="top">I can`t see heaven but i see a great shot. 10</td>', 'I can`t see heaven but i see a great shot. 10', '2003-12-26 08:12:22.000000', NULL, 1),
(523179, 52114, 3306, '<td valign="top">Great angle. Interesting picture. Well done.</td>', 'Great angle. Interesting picture. Well done.', '2003-12-26 08:12:58.000000', NULL, 1),
(523180, 51591, 3306, '<td valign="top">Looks like an oil painting. Excellent use of a longer exposure time. I like the muted colors.</td>', 'Looks like an oil painting. Excellent use of a longer exposure time. I like the muted colors.', '2003-12-26 08:13:46.000000', NULL, 1),
(523181, 52004, 3306, '<td valign="top">This picture has potential but there are a few things that affect its overall effect. It looks a little slanted to the left. It is too flat ie. no feeling of depth. The picture would have been more interesting if the gem were not directly in the center of the picture. The green backround is OK but where is the yellow in the gem coming from?</td>', 'This picture has potential but there are a few things that affect its overall effect. It looks a little slanted to the left. It is too flat ie. no feeling of depth. The picture would have been more interesting if the gem were not directly in the center of the picture. The green backround is OK but where is the yellow in the gem coming from?', '2003-12-26 08:18:11.000000', NULL, 1),
(523182, 51437, 3306, '<td valign="top">Good capture. I would have like it better if you could have gotten some light and detail on the goat rather than just the silohuette.</td>', 'Good capture. I would have like it better if you could have gotten some light and detail on the goat rather than just the silohuette.', '2003-12-26 08:19:18.000000', NULL, 1),
(523184, 51517, 3306, '<td valign="top">Very imaginative. Interesting angle.  I would have liked it better if the fingers were in focus as well but overall a very good picture.</td>', 'Very imaginative. Interesting angle.  I would have liked it better if the fingers were in focus as well but overall a very good picture.', '2003-12-26 08:21:47.000000', NULL, 1),
(523185, 52036, 3306, '<td valign="top">Good idea. Colors seem oversaturated and the picture appears slightly slanted.</td>', 'Good idea. Colors seem oversaturated and the picture appears slightly slanted.', '2003-12-26 08:23:02.000000', NULL, 1),
(523187, 51661, 3306, '<td valign="top">Better start selling some pictures on DP Challenge. Looks like you could use the money! Good shot.</td>', 'Better start selling some pictures on DP Challenge. Looks like you could use the money! Good shot.', '2003-12-26 08:24:01.000000', NULL, 1),
(523188, 51540, 3306, '<td valign="top">Great mirror effect. Very sharp. creative.</td>', 'Great mirror effect. Very sharp. creative.', '2003-12-26 08:25:19.000000', NULL, 1),
(523189, 51880, 3306, '<td valign="top">Don''t know if anyone is going to match this one!! Sorry, bad pun. Interesting picture. I think I would have liked it better if the subject was not centered and there was a little more focus on the razor blade. Also, I think the overall effect would have stood out better with a different colored backround.</td>', 'Don''t know if anyone is going to match this one!! Sorry, bad pun. Interesting picture. I think I would have liked it better if the subject was not centered and there was a little more focus on the razor blade. Also, I think the overall effect would have stood out better with a different colored backround.', '2003-12-26 08:28:10.000000', NULL, 1),
