(523382, 51920, 15401, '<td valign="top">Great!</td>', 'Great!', '2003-12-26 15:25:53.000000', NULL, 1),
(523397, 51476, 10858, '<td valign="top">Unique idea, the story of the photo is one of my favourites here! The transition between life and death is truly one of those mistical boundaries that''s hard to understand exactly and catches most people\''s fantasy! I also like that the living rose is so soft, and the dead one is rough. Just 2 small issues I have to mention here: I would have rotated the photo 1 degree CCW, because the borderline between the 2 sheets is not perfetly vertical. I also would have used one more lightbulb to make the shadow of the living rose more diffused. All together a great job!</td>', 'Unique idea, the story of the photo is one of my favourites here! The transition between life and death is truly one of those mistical boundaries that''s hard to understand exactly and catches most people\''s fantasy! I also like that the living rose is so soft, and the dead one is rough. Just 2 small issues I have to mention here: I would have rotated the photo 1 degree CCW, because the borderline between the 2 sheets is not perfetly vertical. I also would have used one more lightbulb to make the shadow of the living rose more diffused. All together a great job!', '2003-12-26 16:01:39.000000', NULL, 1),
(523401, 51974, 10858, '<td valign="top">Photo is too small and I can''t really catch the "on the edge" message here... :-(</td>', 'Photo is too small and I can''t really catch the "on the edge" message here... :-(', '2003-12-26 16:09:50.000000', NULL, 1),
(523404, 52040, 10858, '<td valign="top">Good idea that the bricks make a frame for your photo. Anyway I would have rotated it a few degrees CCW, because it''s not straight especially on the top. Lighting... well, truly it''s only the edge that''s lighted. :-) Interesting. A mistake that came out well because of the title of the challenge. :-)</td>', 'Good idea that the bricks make a frame for your photo. Anyway I would have rotated it a few degrees CCW, because it''s not straight especially on the top. Lighting... well, truly it''s only the edge that''s lighted. :-) Interesting. A mistake that came out well because of the title of the challenge. :-)', '2003-12-26 16:13:08.000000', NULL, 1),
(523405, 51451, 10858, '<td valign="top">Composition is a bit busy for me, and I can''t really find a main subject on your photo... The idea is good, just needs a better performance.</td>', 'Composition is a bit busy for me, and I can''t really find a main subject on your photo... The idea is good, just needs a better performance.', '2003-12-26 16:14:57.000000', NULL, 1),
(523406, 52092, 10858, '<td valign="top">I would have rotated it 180 degrees, this way I have an unnatural feeling of looking down from a roof. :-) Good idea, the dark part of the top is a bit distracting, I would have inclded just a tiny stripe to show the roof itself.</td>', 'I would have rotated it 180 degrees, this way I have an unnatural feeling of looking down from a roof. :-) Good idea, the dark part of the top is a bit distracting, I would have inclded just a tiny stripe to show the roof itself.', '2003-12-26 16:16:54.000000', NULL, 1),
