(524232, 51694, 15199, '<td valign="top">Amazing capture and sharpness. I also like the feeling of the two black spots in the background</td>', 'Amazing capture and sharpness. I also like the feeling of the two black spots in the background', '2003-12-28 04:16:59.000000', NULL, 1),
(524233, 51437, 15199, '<td valign="top">Great outlines, great angles, awesome</td>', 'Great outlines, great angles, awesome', '2003-12-28 04:17:45.000000', NULL, 1),
(524235, 51502, 15199, '<td valign="top">Great idea and composition. Pity about the highlight on the insect\''s back. A sharper bowl outline might have done a better trick</td>', 'Great idea and composition. Pity about the highlight on the insect\''s back. A sharper bowl outline might have done a better trick', '2003-12-28 04:19:27.000000', NULL, 1),
